INSERT INTO results (diaries_id, type, ei_score, sn_score, tf_score, jp_score, summary) VALUES
    (1, 'ISTP', 2, -2, 0, 2, '「年明けは机の片付けから始めた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (2, 'ESFJ', -2, 0, 2, 0, '「朝は家族で初詣に行き、午後は返せていなかった連絡をまとめて返した」などの記述と回答から、やり取りの中で考えを固める外向寄りの傾向があり、具体と意味を行き来する見方を示し、気持ちや関係性を優先する判断を行い、整理と柔軟さを併用する進め方が見られたため、暫定でESFJ寄りと推定しました。'),
    (3, 'INFJ', 2, 2, 2, -1, '「今日はとても静かな一日だった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、意味や先の広がりを見る直観寄りの見方を示し、気持ちや関係性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でINFJ寄りと推定しました。'),
    (4, 'ISTJ', 2, -2, -1, -2, '「仕事が始まったので、12月のメモを見返して本当に残すべきタスクだけを書き出した」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISTJ寄りと推定しました。'),
    (5, 'ESTJ', -2, -2, -1, -2, '「午前中の長い会議で、誰が何を持つのかがようやくはっきりした」などの記述と回答から、やり取りの中で考えを固める外向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でESTJ寄りと推定しました。'),
    (6, 'ISTP', 2, 0, 0, 2, '「数日気になっていた小さなバグを直した」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (7, 'ISTP', 1, 0, 0, 2, '「寒さが強かったので今日は家で作業した」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (8, 'ESFJ', -2, 0, 2, -1, '「駅の近くで久しぶりの友人と昼を食べた」などの記述と回答から、やり取りの中で考えを固める外向寄りの傾向があり、具体と意味を行き来する見方を示し、気持ちや関係性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でESFJ寄りと推定しました。'),
    (9, 'ISTP', 2, 0, 0, 2, '「今日は荒い下書きを継ぎ足して直すのをやめて、思い切って書き直した」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (10, 'ISTP', 2, 0, 0, 2, '「寝坊して午前中がかなり短くなった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (11, 'ISFJ', 2, -2, 2, -1, '「スーパーは混んでいたけれど、米や卵や洗剤みたいな基本のものを補充すると不思議と落ち着く」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、気持ちや関係性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISFJ寄りと推定しました。'),
    (12, 'ISTJ', 2, -2, -1, -2, '「午後は写真の整理をして、重複しているものを消していった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISTJ寄りと推定しました。'),
    (13, 'ISTP', 2, 0, 0, 2, '「朝から気が重かったメールに、ようやく短く返事を書いた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (14, 'ISTP', 2, 0, 0, 2, '「昼前から雨が降り始めて、そのまま夜まで止まなかった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (15, 'ISTP', 2, -2, 0, 2, '「夜にカレーを作って、いつもより少し長めに煮込んだ」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (16, 'ESTJ', -2, -2, -2, -2, '「手順を文書にまとめたことを同僚が感謝してくれた」などの記述と回答から、やり取りの中で考えを固める外向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でESTJ寄りと推定しました。'),
    (17, 'ESTP', 0, 0, 0, 2, '「土曜日は余白のある一日だった」などの記述と回答から、状況に応じて内外を切り替える傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でESTP寄りと推定しました。'),
    (18, 'ESTP', 0, 0, 0, 2, '「いつもの店が満席で、初めて入るカフェに行った」などの記述と回答から、状況に応じて内外を切り替える傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でESTP寄りと推定しました。'),
    (19, 'ISTJ', 2, 0, -1, -2, '「今日は返信、更新、確認、調整のような保守作業が中心だった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISTJ寄りと推定しました。'),
    (20, 'ISTP', 2, 0, 0, 2, '「単純な作業を急いで余計にややこしくしてしまった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (21, 'ISTP', 2, 0, 0, 2, '「夕方の空が驚くほどきれいで、冷たい建物の上に濃いオレンジが広がっていた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (22, 'ESTJ', 0, -2, -2, -2, '「今月の出費を見直したら、なんとなく買ったものがいくつか目についた」などの記述と回答から、状況に応じて内外を切り替える傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でESTJ寄りと推定しました。'),
    (23, 'ESTP', 0, 0, 0, 2, '「チャットの行き違いが少し面倒になりかけたが、短い通話ですぐ収まった」などの記述と回答から、状況に応じて内外を切り替える傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でESTP寄りと推定しました。'),
    (24, 'ISTP', 2, -1, 0, 2, '「午前中にシーツを洗い、部屋の空気を入れ替え、台所も片づけた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (25, 'ISTJ', 2, -2, 0, -2, '「日曜の終わりに来週の弁当の下準備をした」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準と感情を併せて見る判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISTJ寄りと推定しました。'),
    (26, 'ISTP', 2, -2, -1, 2, '「午後のレビューで、私たちが違う指標を見ていたことが分かった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (27, 'ISTP', 2, 0, 0, 2, '「苦手意識のある分野を夜に少し勉強した」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (28, 'ISTP', 2, 0, 0, 2, '「暖房の効きが弱くて、今日は家の中でも厚手の服を重ねた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (29, 'ESFJ', -2, 0, 2, -1, '「夕食のあとで実家に電話をした」などの記述と回答から、やり取りの中で考えを固める外向寄りの傾向があり、具体と意味を行き来する見方を示し、気持ちや関係性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でESFJ寄りと推定しました。'),
    (30, 'ISTP', 2, -2, -1, 2, '「今日は退屈だけれど必要な書類を仕上げることにほとんどの集中力を使った」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (31, 'ISTJ', 2, -2, -1, -2, '「一月の最後は拍子抜けするほど静かだった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISTJ寄りと推定しました。'),
    (32, 'INTP', 2, 2, 0, 2, '「二月の始まりはよく晴れて、空気だけが冷たかった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、意味や先の広がりを見る直観寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でINTP寄りと推定しました。'),
    (33, 'ISTP', 2, 0, 0, 2, '「朝一番の不具合報告は大きく見えたが、実際にはそこまで深刻ではなかった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (34, 'INTP', 2, 2, 0, 2, '「数週間迷っていたけれど、ようやく新しいノートを買った」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、意味や先の広がりを見る直観寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でINTP寄りと推定しました。'),
    (35, 'ISTP', 2, 0, 0, 2, '「電車が遅れて、思いがけずホームで待つ時間ができた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (36, 'ISTP', 2, -2, 0, 2, '「冷蔵庫に残っていたもので適当にスープを作ったら、予定していた献立よりずっとおいしくできた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (37, 'ESTJ', 0, -2, -1, -2, '「一人で難しく考えすぎていた問題を、同僚との会話であっさり整理できた」などの記述と回答から、状況に応じて内外を切り替える傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でESTJ寄りと推定しました。'),
    (38, 'ISTP', 1, 0, 0, 2, '「土曜の午後は図書館の窓際の席で過ごした」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (39, 'ISTP', 2, -2, 0, 2, '「洗濯、買い出し、作り置きで一日がほとんど終わった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (40, 'ISTP', 2, 0, 0, 2, '「朝から妙に体が重くて、作業を恥ずかしいほど細かく分けた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (41, 'ENFP', 0, 2, 1, 2, '「駅からの帰り道で梅の花が咲いているのに気づいた」などの記述と回答から、状況に応じて内外を切り替える傾向があり、意味や先の広がりを見る直観寄りの見方を示し、気持ちや関係性を優先する判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でENFP寄りと推定しました。'),
    (42, 'ISTP', 2, 0, 0, 2, '「週の真ん中の祝日で、全体の速度が少し緩んだ」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (43, 'ISTP', 2, -1, 0, 2, '「古いメモを見返していたら、当時より今のほうが良さが分かる案が一つあった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (44, 'ENTP', -1, 2, 0, 2, '「今日は何かを作るより、関係する人たちをつなぐ時間のほうが長かった」などの記述と回答から、やり取りの中で考えを固める外向寄りの傾向があり、意味や先の広がりを見る直観寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でENTP寄りと推定しました。'),
    (45, 'ENTP', 0, 2, 0, 2, '「いつもより長く歩いて、あまり行かない住宅街まで足を伸ばした」などの記述と回答から、状況に応じて内外を切り替える傾向があり、意味や先の広がりを見る直観寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でENTP寄りと推定しました。'),
    (46, 'ISTP', 2, 0, 0, 2, '「日曜の夜はあっという間に来る」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (47, 'ISTP', 2, 0, 0, 2, '「ほぼ終わったと思っていた原稿を、結局は構成から直すことになった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (48, 'ENFJ', 0, 2, 2, -1, '「一日中風が強くて、街全体が落ち着かない音を立てていた」などの記述と回答から、状況に応じて内外を切り替える傾向があり、意味や先の広がりを見る直観寄りの見方を示し、気持ちや関係性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でENFJ寄りと推定しました。'),
    (49, 'ISTJ', 2, 0, -1, -2, '「ずっと忘れていたサブスクをやっと解約した」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISTJ寄りと推定しました。'),
    (50, 'ESTJ', -2, 0, -1, -2, '「後輩の丁寧な質問で、こちらの説明不足がはっきりした」などの記述と回答から、やり取りの中で考えを固める外向寄りの傾向があり、具体と意味を行き来する見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でESTJ寄りと推定しました。'),
    (51, 'INTP', 2, 2, 0, 2, '「朝食のトーストを一度焦がしてしまったが、縁起の悪い兆しみたいに扱わずに笑って済ませた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、意味や先の広がりを見る直観寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でINTP寄りと推定しました。'),
    (52, 'ESTP', 0, 0, 0, 2, '「午後は町のあちこちで用事を済ませているうちに過ぎていった」などの記述と回答から、状況に応じて内外を切り替える傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でESTP寄りと推定しました。'),
    (53, 'ISTJ', 2, -2, -1, -2, '「日曜はノートPCの古いファイルを整理して、必要なものだけ名前を付け直した」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、手元の事実や手順を見る感覚寄りの見方を示し、基準や妥当性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISTJ寄りと推定しました。'),
    (54, 'ESTP', -1, 0, 0, 2, '「短い定例が思いがけず率直な場になった」などの記述と回答から、やり取りの中で考えを固める外向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でESTP寄りと推定しました。'),
    (55, 'ISFJ', 1, 0, 2, -1, '「夜は寒くて外食に流れたくなったけれど、結局家で簡単なものを作った」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、気持ちや関係性を優先する判断を行い、段取りや区切りを整えて進める姿勢が見られたため、暫定でISFJ寄りと推定しました。'),
    (56, 'ISTP', 2, 0, 0, 2, '「小さな選択肢を比べるのに時間をかけすぎた」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (57, 'ISTP', 2, 0, 0, 2, '「朝から終わりまで少しちぐはぐな一日だった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (58, 'ISTP', 2, 0, 0, 2, '「手こずった作業を終えたあと、普段より少しだけいい昼食をとった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、具体と意味を行き来する見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でISTP寄りと推定しました。'),
    (59, 'INTP', 2, 2, 0, 2, '「二月の終わりは静かだった」などの記述と回答から、一人で整理しながら進める内向寄りの傾向があり、意味や先の広がりを見る直観寄りの見方を示し、基準と感情を併せて見る判断を行い、余白を残して柔軟に動く進め方が見られたため、暫定でINTP寄りと推定しました。');
